// ======================================================
// OBTENER DATOS DESDE EL WEBHOOK
// ======================================================
const input = $input.first().json;
const body = input.body ?? {};

// Convertimos ambos campos a texto y quitamos espacios
const celular = String(body.Celular ?? '').trim();
const telefonoFijo = String(body.Telefono ?? '').trim();

// Prioridad: celular -> teléfono fijo -> null
const telefono = celular || telefonoFijo || null;

const notas = String(body.pilot_notes ?? '');
const productoInteres = String(body.pilot_product_of_interest ?? '').trim();

// ======================================================
// NORMALIZADOR ARGENTINA
// FORMATO DE SALIDA: 549XXXXXXXXXX
// ======================================================
function normalizarTelefonoArgentina(numero) {
  if (!numero) {
    return null;
  }

  // Eliminar espacios, guiones, paréntesis, +, etc.
  let limpio = String(numero).replace(/\D/g, '');

  if (!limpio) {
    return null;
  }

  // ==================================================
  // CASO 1: Ya viene como 549...
  // Ejemplo: 5491172270714
  // ==================================================
  if (limpio.startsWith('549') && limpio.length >= 13) {
    return limpio;
  }

  // ==================================================
  // CASO 2: Viene como 54...
  // Ejemplo: 541172270714
  // Se agrega el 9 después del 54
  // ==================================================
  if (limpio.startsWith('54') && limpio.length >= 12) {
    return `549${limpio.slice(2)}`;
  }

  // ==================================================
  // CASO 3: Viene como 0 + código de área + número
  // Ejemplo: 01172270714
  // ==================================================
  if (limpio.startsWith('0')) {
    limpio = limpio.slice(1);
  }

  // ==================================================
  // CASO 4: Viene con 15 después del código de área
  // Ejemplo CABA: 0111572270714
  // Después de sacar el 0 queda: 111572270714
  //
  // Esta corrección está pensada para números de CABA.
  // ==================================================
  if (limpio.startsWith('1115') && limpio.length === 12) {
    limpio = `11${limpio.slice(4)}`;
  }

  // ==================================================
  // CASO 5: Área + número
  // Argentina normalmente tiene 10 dígitos nacionales
  // Ejemplos:
  // 1172270714
  // 3815765949
  // ==================================================
  if (limpio.length === 10) {
    return `549${limpio}`;
  }

  // ==================================================
  // NO VÁLIDO
  // ==================================================
  return null;
}

// ======================================================
// EXTRAER MODELO DE INTERÉS
// ======================================================
function extraerModelo(notasLead, producto) {
  // Prioridad 1: campo específico del producto
  if (producto) {
    return producto;
  }

  // Prioridad 2: buscar dentro de las notas
  const match = notasLead.match(
    /Modelo de inter[eé]s:\s*([^\n.]+)/i
  );

  if (match?.[1]) {
    const modeloEncontrado = match[1].trim();
    return modeloEncontrado || null;
  }

  return null;
}

// ======================================================
// NORMALIZAR Y EXTRAER DATOS
// ======================================================
const whatsapp = normalizarTelefonoArgentina(telefono);
const modelo = extraerModelo(notas, productoInteres);

// ======================================================
// DETERMINAR MOTIVO DE ERROR
// ======================================================
let motivoInvalido = null;

if (!telefono) {
  motivoInvalido =
    'El webhook no recibió pilot_cellphone ni pilot_phone';
} else if (!whatsapp) {
  motivoInvalido =
    'El teléfono recibido no tiene un formato o cantidad de dígitos válida';
}

// ======================================================
// SALIDA
// ======================================================
return [
  {
    json: {
      whatsapp,
      valido: whatsapp !== null,
      original: telefono,

      telefono_celular_recibido: celular,
      telefono_fijo_recibido: telefonoFijo,

      motivo_invalido: motivoInvalido,
      modelo
    }
  }
];

// ======================================================
// Webhook → preparar disparo restringido Accesorios
// ======================================================
const root = $input.first()?.json || {};
const body = root.body || root;

// ======================================================
// DATOS DEL CLIENTE
// ======================================================
const firstname =
  String(body.Nombre_Cliente || '').trim() ||
  'Cliente';

const marca =
  String(body.Marca || '').trim();

const modelo =
  String(body.Modelo || '').trim();

const version =
  String(body.Version || '').trim();

// ======================================================
// TELÉFONO
// ======================================================
let telefono =
  body.Celular ||
  body.Telefono ||
  null;

// ======================================================
// NORMALIZADOR ARGENTINA
// ======================================================
function normalizarTelefonoArgentina(numero) {
  if (!numero) return null;

  let limpio = String(numero).replace(/\D/g, '');

  if (limpio.startsWith('549') && limpio.length === 13) {
    return limpio;
  }

  if (limpio.startsWith('54') && limpio.length === 12) {
    return '549' + limpio.slice(2);
  }

  if (limpio.startsWith('0')) {
    limpio = limpio.slice(1);
  }

  if (limpio.length === 10) {
    return '549' + limpio;
  }

  return null;
}

const whatsapp = normalizarTelefonoArgentina(telefono);

// ======================================================
// NORMALIZAR DATOS
// ======================================================
const marcaNorm = marca
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

const modeloNorm = modelo
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

// ======================================================
// CONSTANTES TWILIO AUTOFANCE
// ======================================================
const ACCOUNT_SID = 'TWILIO_SID_OCULTO';

const MESSAGING_SERVICE_SID =
  'MG2f017dd3c25d710216538e8064169bb7';

const FROM_PHONE = 'whatsapp:+5491125599175';

const TWILIO_CREDENTIAL_REF = 'Twillio Autofrance';

// ======================================================
// TEMPLATE ACCESORIOS
// ======================================================

const CONTENT_SID = 'HX12c903cf080041eed4d5c7232f09c4e3';

// ======================================================
// CONTENT VARIABLES
// ======================================================

const contentVariablesObj = {
  '1': firstname
};

const contentVariables =
  JSON.stringify(contentVariablesObj);

// ======================================================
// VALIDACIONES
// ======================================================
const telefonoValido = whatsapp !== null;

const datosClienteValidos =
  firstname !== '' &&
  firstname !== 'Cliente';

const templateValido =
  CONTENT_SID !== '' &&
  CONTENT_SID !== 'PEGAR_CONTENT_SID_ACA';

const valido =
  telefonoValido &&
  datosClienteValidos &&
  templateValido;

// ======================================================
// SALIDA
// ======================================================
return [
  {
    json: {
      valido,

      telefonoValido,
      datosClienteValidos,
      templateValido,

      whatsapp,
      to_phone: whatsapp,

      firstname,

      marca,
      marcaNorm,

      modelo,
      modeloNorm,

      version,

      account_sid: ACCOUNT_SID,
      messaging_service_sid: MESSAGING_SERVICE_SID,
      from_phone: FROM_PHONE,

      content_sid: CONTENT_SID,
      content_variables: contentVariables,

      original: telefono,

      twilio_credential_ref: TWILIO_CREDENTIAL_REF,

      source: 'n8n:autofrance-accesorios-restricciones',

      payload_json: {
        firstname,
        marca,
        modelo,
        version,
        whatsapp,
        contentVariables
      }
    }
  }
];
